t = int(input())

for _ in range(t):
    n, m = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(n)]

    # Tạo ma trận C kích thước n x n
    C = [[0] * n for _ in range(n)]

    # Tính C = A * A^T
    for i in range(n):
        for j in range(n):
            s = 0
            for k in range(m):
                s += A[i][k] * A[j][k]
            C[i][j] = s

