def solve_matrix_transpose_product():
    t = int(input())

    for _ in range(t):
        n, m = map(int, input().split())

        matrix_a = []
        for _ in range(n):
            row = list(map(int, input().split()))
            matrix_a.append(row)

        matrix_c = [[0] * n for _ in range(n)]

        for i in range(n):
            for j in range(n):
                sum_val = 0
                for k in range(m):
                    sum_val += matrix_a[i][k] * matrix_a[j][k]
                matrix_c[i][j] = sum_val

        for row in matrix_c:
            print(*(row))


