t = int(input())

for _ in range(t):
    n, m = map(int, input().split())

    A = []
    for _ in range(n):
        row = list(map(int, input().split()))
        A.append(row)

    C = []
    for i in range(n):
        C.append([0]*n)

    for i in range(n):
        for j in range(n):
            sum_ij = 0
            for k in range(m):
                sum_ij += A[i][k] * A[j][k]
            C[i][j] = sum_ij

    for row in C:
        print(" ".join(map(str, row)))

