t = int(input())      # số test

for _ in range(t):
    # Đọc n và m, đảm bảo đọc đúng
    while True:
        line = read_ints()
        if len(line) == 2:
            n, m = line
            break

    A = []  # ma trận A

    # Đọc đủ n hàng, mỗi hàng có m số
    while len(A) < n:
        row = read_ints()
        if len(row) == m:
            A.append(row)

    # Tính ma trận C = A * A^T
    C = []
    for i in range(n):
        rowC = []
        for j in range(n):
            total = 0
            for k in range(m):
                total += A[i][k] * A[j][k]
            rowC.append(total)
        C.append(rowC)

    # In kết quả
    for row in C:
        print(*row)

