    # Đọc n và m, đảm bảo đọc đúng
    while True:
        line = read_ints()
        if len(line) == 2:
            n, m = line
            break

    A = []  # ma trận A

    # Đọc đủ n hàng, mỗi hàng có m số
    while len(A) < n:
