    # Tính ma trận C = A * A^T
    C = []
    for i in range(n):
        rowC = []
        for j in range(n):
            total = 0
            for k in range(m):
                total += A[i][k] * A[j][k]
            rowC.append(total)
        C.append(rowC)

    # In kết quả
    for row in C:
        print(*row)

