def transpose(matrix):
    return [[matrix[i][j] for i in range(len(matrix))] 
            for j in range(len(matrix[0]))]

def mul_matrix(A, B):
    n = len(A)          
    m = len(A[0])       
    p = len(B[0])       

    C = [[0] * p for _ in range(n)]

    for i in range(n):
        for j in range(p):
            for k in range(m):
                C[i][j] += A[i][k] * B[k][j]

    return C

