import sys

def solve():
    # Đọc toàn bộ dữ liệu đầu vào từ input chuẩn (stdin)
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Đọc số lượng test case
        t = int(next(iterator))
    except StopIteration:
        return

    for _ in range(t):
        try:
            # Đọc n và m
            n = int(next(iterator))
            m = int(next(iterator))

            # Đọc ma trận A
            A = []
            for i in range(n):
                row = []
                for j in range(m):
                    row.append(int(next(iterator)))
                A.append(row)

            # Tính toán ma trận kết quả C = A * A^T
            # Ma trận C sẽ có kích thước n x n
            C = []
            for i in range(n):
                row_c = []
                for j in range(n):
                    value = 0
                    # Áp dụng công thức: C[i][j] = sum(A[i][k] * A[j][k])
                    for k in range(m):
                        value += A[i][k] * A[j][k]
                    row_c.append(value)
                C.append(row_c)

            # In kết quả
            for row in C:
                # Dùng *row để in các phần tử cách nhau bởi dấu cách
                print(*row)

        except StopIteration:
            break

if __name__ == '__main__':
    solve()

